{
"name": "pro",
"max_spend_per_period": 49.00,
"max_spend_per_session": 5.00,
"model_limits": {
"gpt-4o": {"max_tokens_per_period": 50000},
"gpt-4o-mini": {"max_tokens_per_period": 200000}
},
"cost_rates": {
